/* Browser-side equivalent of the preserved FastAPI data queries. */
(() => {
  const base = new URL('../data/', document.currentScript.src);
  const cache = new Map();
  const geometryKeys = new Set();
  const lowMemoryDevice = Number(navigator.deviceMemory || 4) <= 2;
  const MAX_GEOMETRY = lowMemoryDevice ? 10 : 20;
  const GEO_BATCH_SIZE = lowMemoryDevice ? 4 : 6;
  const intersects = (a, b) => a[0] <= b[2] && a[2] >= b[0] && a[1] <= b[3] && a[3] >= b[1];
  async function read(path) {
    if (cache.has(path)) { if (geometryKeys.has(path)) { geometryKeys.delete(path); geometryKeys.add(path); } return cache.get(path); }
    const request = fetch(new URL(path, base)).then(response => { if (!response.ok) throw new Error(`数据加载失败（${response.status}），请重试`); return response.json(); }).catch(error => { cache.delete(path); geometryKeys.delete(path); throw error; });
    cache.set(path, request);
    if (path.startsWith('geo/')) { geometryKeys.add(path); while (geometryKeys.size > MAX_GEOMETRY) { const oldest = geometryKeys.values().next().value; geometryKeys.delete(oldest); cache.delete(oldest); } }
    return request;
  }
  function failure(message, status = 404) { const error = new Error(message); error.status = status; throw error; }
  function bbox(value) { if (value == null) return null; const b = value.split(',').map(Number); if (b.length !== 4 || b.some(n => !Number.isFinite(n)) || !(b[0] >= -180 && b[2] <= 180 && b[0] <= b[2] && b[1] >= -90 && b[3] <= 90 && b[1] <= b[3])) failure('bbox 必须是有效的西、南、东、北四个经纬度', 422); return b; }
  function yearValue(value, minimum = 1921, maximum = new Date().getFullYear()) { if (value == null) return null; const number = Number(value); if (!/^\d+$/.test(String(value)) || number < minimum || number > maximum) failure('年份不在有效范围内', 422); return number; }
  const compact = item => Object.fromEntries(['id','code','name','level','parent','full_name','ancestor_ids','bbox','label_point','child_count','geometry_status','coverage_status','aliases'].map(key => [key,item[key] ?? null]));
  const normalize = value => String(value || '').normalize('NFKC').replaceAll('臺','台').toLowerCase();
  async function allBattles() { let extra = []; try { extra = await read('history/battles_post1949.json'); } catch {} return [...await read('history/battles.json'), ...extra]; }
  async function sourceRecords(ids) { const source = await read('history/sources.json'); return [...new Set(ids || [])].filter(id => id in source).map(id => source[id]); }
  function battleSummary(item) { const result = Object.fromEntries(Object.entries(item).filter(([key]) => !['routes','stages'].includes(key))); const participants = result.participants || []; result.faction ??= participants.some(p => /红军|解放军/.test(String(p))) ? 'ccp' : 'other'; result.branch ??= '陆军'; result.commanders ??= []; result.forces ??= participants.map(name => ({name, faction: result.faction, branch: result.branch, strength: null, strength_precision: 'not_published'})); return result; }
  function dateValue(value) { if (!value) return null; const text=String(value), candidate=text.length===4?`${text}-01-01`:text.length===7?`${text}-01`:text, date=new Date(`${candidate}${candidate.length===10?'T00:00:00Z':'Z'}`); return Number.isNaN(date.getTime())?null:date; }
  function endDate(value) { const date=dateValue(value); if(!date)return null; const text=String(value); if(text.length===4)return new Date(Date.UTC(date.getUTCFullYear()+1,0,1)-1); if(text.length===7)return new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,1)-1); if(text.length===10)return new Date(date.getTime()+86400000-1); return date; }
  async function battleTimeline(item, at, granularity) { const start=dateValue(item.start_date)||new Date(-8640000000000000),end=endDate(item.end_date)||start; let cursor=at?dateValue(at):end; if(!cursor)failure('at 必须是 ISO 日期或日期时间',422); const requested=cursor; cursor=cursor<end?cursor:end; let effective=granularity||'day'; if(effective==='hour'&&!(item.stages||[]).some(stage=>String(stage.date||'').includes('T')))effective='day'; const routes=(item.routes||[]).map(route=>{const copy={...route},segments=route.segments;if(segments){const visible=segments.filter(segment=>(dateValue(segment.end_at)||start)<=cursor);copy.segments=visible;copy.paths=visible.map(segment=>segment.coordinates||[]);copy.coordinates=copy.paths.length===1?copy.paths[0]:[];copy.playback_mode='dated_segments';}else if(cursor<start)copy.coordinates=[];if(cursor<start){copy.coordinates=[];copy.paths=[];}copy.visible_until=cursor.toISOString().slice(0,10);return copy;});return {id:item.id,battle:battleSummary(item),at:cursor.toISOString().slice(0,16),granularity:effective,requested_at:requested.toISOString().slice(0,16),start_at:start.toISOString().slice(0,16),end_at:end.toISOString().slice(0,16),routes,stages:(item.stages||[]).filter(stage=>(dateValue(stage.date)||new Date(8640000000000000))<=cursor),sources:await sourceRecords(item.source_ids)}; }
  async function geo(level, bounds) { const manifest=await read('geo-manifest.json'),layer=manifest.levels[level]; if(!layer)failure('无效行政层级',422); const chunks=layer.chunks.filter(chunk=>!bounds||intersects(chunk.bbox,bounds)),payloads=[]; for(let i=0;i<chunks.length;i+=GEO_BATCH_SIZE)payloads.push(...await Promise.all(chunks.slice(i,i+GEO_BATCH_SIZE).map(chunk=>read(chunk.path)))); const order=new Map(layer.order.map((id,index)=>[String(id),index])),features=payloads.flatMap(chunk=>chunk.features).filter(feature=>!bounds||intersects(feature.bbox,bounds)); features.sort((a,b)=>(order.get(String(a.properties.id))??0)-(order.get(String(b.properties.id))??0)); return {type:'FeatureCollection',features,source_count:layer.source_count,canonical_count:layer.canonical_count,version:manifest.version}; }
  async function featureFor(id) { const manifest=await read('geo-manifest.json'),path=manifest.regions[id]; if(!path)return null; return (await read(path)).features.find(feature=>String(feature.properties.id)===String(id))||null; }
  async function control(year,bounds,at) { const records=(await read('history/control-records.json')).records,moment=at?dateValue(at):new Date(Date.UTC(year,11,31,23,59,59)),features=[]; for(const record of records){if(!moment||(dateValue(record.start_at)>moment)||(endDate(record.end_at)<moment))continue;for(const id of record.admin_ids||[]){const carrier=await featureFor(String(id));if(!carrier||bounds&&carrier.bbox&&!intersects(carrier.bbox,bounds))continue;const properties={...record,admin_id:id,name:carrier.properties.name,geometry_role:'modern_administrative_carrier'};delete properties.admin_ids;features.push({type:'Feature',id:`${record.id}:${id}`,properties,geometry:carrier.geometry,bbox:carrier.bbox});}}return {type:'FeatureCollection',features,at:moment?.toISOString(),sources:await read('history/military-sources.json'),coverage_note:'未有可靠范围记录的地区保持中性；现代行政面只作地点范围载体，并非复原历史疆界'}; }
  async function query(url) {
    const {pathname,searchParams:params}=new URL(url,location.origin),parts=pathname.split('/').filter(Boolean).map(decodeURIComponent); if(parts[0]!=='api')failure('不支持的数据查询'); const resource=parts[1],id=parts[2];
    if(resource==='health')return {status:'ok',mode:'static'}; if(resource==='geo-index')return read('geo-index.json'); if(resource==='geo-status')return read('geo-status.json'); if(resource==='geo')return geo(id,bbox(params.get('bbox'))); if(resource==='world'){const world=await read('world.json'),bounds=bbox(params.get('bbox'));return {...world,features:bounds?world.features.filter(feature=>!feature.bbox||intersects(feature.bbox,bounds)):world.features};}
    if(resource==='history-catalog'){const result={...await read('history/catalog.json')},battles=await allBattles();result.postwar_battle_count=battles.filter(item=>Number(item.start_date.slice(0,4))>=1950).length;result.postwar_years=[...new Set(battles.flatMap(item=>{const a=Number(item.start_date.slice(0,4)),b=Number(item.end_date.slice(0,4));return Array.from({length:b-a+1},(_,i)=>a+i);}))].sort((a,b)=>a-b);return result;}
    if(resource==='events'){const all=await read('events.json');if(id)return all.find(event=>event.id===id)||failure('未找到该历史内容');const mode=params.get('mode')||'ordinary',year=yearValue(params.get('year'));if(!['ordinary','long_march','anti_japanese','time','person'].includes(mode))failure('无效模式',422);const person=params.get('person'),region=params.get('region'),kind=params.get('kind'),items=all.filter(item=>(!['long_march','anti_japanese'].includes(mode)||(item.themes||[]).includes(mode))&&(year==null||item.year===year)&&(mode!=='person'||!person||(item.people||[]).includes(person))&&(!region||[item.province,item.city,item.district].includes(region))&&(!kind||item.kind===kind));return {items,count:items.length,mode,year};}
    if(resource==='persons'){if(!id)return {items:await read('persons.json')};const journeys=await read('history/journeys.json'),item=journeys[id];if(!item)failure('未找到该人物行程');return {...item,sources:await sourceRecords(item.nodes.flatMap(node=>node.source_ids||[]))};}
    if(resource==='routes')return {routes:(await read('routes.json'))[id]||[]};
    if(resource==='regions'){const regions=await read('regions.json'),item=regions[id];if(id&&parts[3]==='stories'){const name=item?.name||id,year=yearValue(params.get('year'),1860),province=item?.ancestor_ids?.length?regions[item.ancestor_ids[0]].name:null,items=(await read('events.json')).filter(event=>[event.province,event.city,event.district].includes(name)&&(!province||event.province===province)&&(year==null||event.year===year));return {region:id,items,count:items.length};}if(id){if(parts[3]==='geometry'){if(!item)failure('未找到该行政区');if(item.geometry_status!=='available')return {region:item,geometry:null,status:'missing',locate_parent:item.parent};const feature=await featureFor(id);if(!feature)failure('目录与边界不一致',503);return feature;}return item||failure('未找到该行政区');}const text=params.get('query')||'',parent=params.get('parent'),level=params.get('level'),offset=Number(params.get('offset')||0),limit=Number(params.get('limit')||50),terms=normalize(text).trim().split(/\s+/).filter(Boolean),selected=Object.values(regions).filter(item=>(!parent||item.parent===parent)&&(!level||item.level===level)&&terms.every(term=>normalize([item.id,item.code||'',item.full_name,...(item.aliases||[])].join(' ')).includes(term))).sort((a,b)=>(a.full_name||'').localeCompare(b.full_name||'')||String(a.id).localeCompare(String(b.id)));return {items:selected.slice(offset,offset+limit).map(compact),count:selected.length,offset,limit,version:(await read('geo-manifest.json')).version};}
    if(resource==='history'){const year=yearValue(id,1921),bounds=bbox(params.get('bbox')),battles=await allBattles();if(year>=1951)return {year,display_mode:'modern',snapshot_date:null,territories:[],battles:battles.filter(b=>Number(b.start_date.slice(0,4))<=year&&year<=Number(b.end_date.slice(0,4))).map(battleSummary),sources:[],military_layers:'battle_routes_only',coverage_status:'no_historical_territory',note:'1951年起使用现代行政底图，并按年份展示战役与军事行动的公开记录。'};const annual=(await read('history/annual.json'))[String(year)],territories=annual.territories.filter(region=>!bounds||!region.bbox||intersects(region.bbox,bounds));return {...annual,display_mode:'historical',territories,battles:battles.filter(b=>Number(b.start_date.slice(0,4))<=year&&year<=Number(b.end_date.slice(0,4))).map(battleSummary),sources:await sourceRecords([...annual.source_ids,...territories.flatMap(region=>region.source_ids||[])]),total_territories:annual.territories.length};}
    if(resource==='control')return control(Number(params.get('year')||1933),bbox(params.get('bbox')),params.get('at'));
    if(resource==='units'){let units=(await read('history/unit-movements.json')).units;const year=params.get('year'),q=normalize(params.get('q')||''),category=params.get('category'),battleId=params.get('battle_id');if(category)units=units.filter(unit=>(unit.categories||[]).includes(category));if(battleId)units=units.filter(unit=>(unit.battle_ids||[]).includes(battleId));return {units:units.filter(unit=>(year==null||Number(unit.start_at.slice(0,4))<=Number(year)&&Number(year)<=Number(unit.end_at.slice(0,4)))&&normalize(unit.name).includes(q))};}
    if(resource==='battles'){const battles=await allBattles();if(!id){const year=params.get('year'),phase=params.get('phase'),theater=params.get('theater'),q=normalize(params.get('q')||''),items=battles.filter(item=>(year==null||Number(item.start_date.slice(0,4))<=Number(year)&&Number(year)<=Number(item.end_date.slice(0,4)))&&(!phase||item.phase===phase)&&(!theater||normalize(item.theater||item.location).includes(normalize(theater)))&&(!q||normalize([item.id,item.name,item.phase,item.location,item.summary,item.theater].join(' ')).includes(q)));return {items:items.map(item=>({...battleSummary(item),sources:[]})),count:items.length,year:year?Number(year):null,phase,theater,q:params.get('q')};}const item=battles.find(item=>item.id===id);if(!item)failure('未找到该战役');if(parts[3]==='timeline')return battleTimeline(item,params.get('at'),params.get('granularity')||'day');return {...battleSummary(item),sources:await sourceRecords(item.source_ids)};}
    if(resource==='military'&&id==='sources')return read('history/military-sources.json'); failure('不支持的数据查询');
  }
  // Static data is read-only in the browser; avoid cloning multi-megabyte
  // event and index payloads on every query.
  window.RedMapData={getJSON:async url=>query(url)};
})();
